import type { AuthenticatedActor } from '../modules/identity';
import type { Container } from './container';

// `Env` is generated by `wrangler types` from wrangler.jsonc (and .dev.vars when present).
// Secrets and values the owner sets with Wrangler are declared here; they are optional because
// a fresh deployment does not have them yet and the app must answer 503 instead of crashing.
export type AppEnv = Env & {
  TELEGRAM_BOT_TOKEN?: string;
  TELEGRAM_WEBHOOK_SECRET?: string;
  /** Optional override: JSON of the Bot API `getMe` result. Without it the identity stored by connect is used. */
  BOT_INFO?: string;
  /** YouTube Data API v3 key for content analytics (public counters only). */
  YOUTUBE_API_KEY?: string;
  /** OpenAI key for the AI writer (Worker secret the owner sets; never logged or returned). */
  OPENAI_API_KEY?: string;
  /** TikTok for Developers app keys (Login Kit + Display API). */
  TIKTOK_CLIENT_KEY?: string;
  TIKTOK_CLIENT_SECRET?: string;
  /** A GitHub token with no scopes: the game-files tracker (owner, 24.10.2026). */
  GITHUB_TOKEN?: string;
  /** STRATZ GraphQL token: pick and win rates for the rubrics (owner, 25.10.2026). */
  STRATZ_TOKEN?: string;
  /** The owner's stats bridge (`bridge/stats-bridge`), e.g. https://alexeev-stats.onrender.com: STRATZ refuses Cloudflare. */
  STATS_BRIDGE_URL?: string;
  /** The key commenters are hashed with (rubric scheduler stage 2); without it comments are not kept. */
  AUDIENCE_HASH_KEY?: string;
};

export type AppBindings = {
  Bindings: AppEnv;
  Variables: { requestId: string; container: Container; actor: AuthenticatedActor };
};
